                                    ? (tbl_prog_memory_hit_word - TBL_PROG_MEMORY_MIDDLE) : 14'd0;
    wire [13:0] tbl_prog_memory_clamped = (tbl_prog_memory_new_base > TBL_PROG_MEMORY_MAX_BASE)
                                  ? TBL_PROG_MEMORY_MAX_BASE : tbl_prog_memory_new_base;
    // The window is stable while the followed word stays inside it, and it
    // re-centres on the word when it leaves the visible range.
    wire tbl_prog_memory_in_window = (tbl_prog_memory_access_word >= tbl_prog_memory_base)
                          && (tbl_prog_memory_access_word < tbl_prog_memory_base + TBL_PROG_MEMORY_ROWS);
    wire [13:0] tbl_prog_memory_next_base = tbl_prog_memory_in_window ? tbl_prog_memory_base
                                                          : tbl_prog_memory_access_base;
    // The marked row of the table.
    wire tbl_prog_memory_is_marked = tbl_prog_memory_marked_valid
                             && (tbl_prog_memory_addr == tbl_prog_memory_marked);
    // The word the access touches.  The mask is what the memory does in
    // hardware: the index is truncated to the depth of the array, so an
    // access beyond the memory lands in a lower word and the table marks
    // the word the hardware really used.
    wire [13:0] tbl_data_memory_hit_word = (dm_addr >> 2) & TBL_DATA_MEMORY_WORD_MASK;
    // The window base: the word sits in the middle of the table.
    wire [13:0] tbl_data_memory_new_base = (tbl_data_memory_hit_word > TBL_DATA_MEMORY_MIDDLE)
                                    ? (tbl_data_memory_hit_word - TBL_DATA_MEMORY_MIDDLE) : 14'd0;
    wire [13:0] tbl_data_memory_clamped = (tbl_data_memory_new_base > TBL_DATA_MEMORY_MAX_BASE)
                                  ? TBL_DATA_MEMORY_MAX_BASE : tbl_data_memory_new_base;
    // The window is stable while the followed word stays inside it, and it
    // re-centres on the word when it leaves the visible range.
    wire tbl_data_memory_in_window = (tbl_data_memory_access_word >= tbl_data_memory_base)
                          && (tbl_data_memory_access_word < tbl_data_memory_base + TBL_DATA_MEMORY_ROWS);
    wire [13:0] tbl_data_memory_next_base = tbl_data_memory_in_window ? tbl_data_memory_base
                                                          : tbl_data_memory_access_base;
    // The marked row of the table.
    wire tbl_data_memory_is_marked = tbl_data_memory_marked_valid
                             && (tbl_data_memory_addr == tbl_data_memory_marked);

    logic [GRP_W-1:0] grp_ctr;

    // Register table, stage 1: the row of the character being written.
    localparam logic [415:0] REG_ADDR = {13'd6492, 13'd6332, 13'd6172, 13'd6012, 13'd5852, 13'd5692, 13'd5532, 13'd5372, 13'd5212, 13'd5052, 13'd4892, 13'd4732, 13'd4572, 13'd4412, 13'd4252, 13'd4092, 13'd3932, 13'd3772, 13'd3612, 13'd3452, 13'd3292, 13'd3132, 13'd2972, 13'd2812, 13'd2652, 13'd2492, 13'd2332, 13'd2172, 13'd2012, 13'd1852, 13'd1692, 13'd1532};
    logic [31:0] reg_value;
    logic [12:0] reg_addr;
    logic [2:0]  reg_col;

    // Snapshot bank - the whole screen is rendered from one instant
    logic [31:0] snap_alu_a;
    logic [31:0] snap_alu_b;
    logic [4:0] snap_alu_op;
    logic [31:0] snap_alu_res;
    logic [1:0] snap_alua_src;
    logic [0:0] snap_alub_src;
    logic [4:0] snap_br_op;
    logic [0:0] snap_branch;
    logic [0:0] snap_branch_flush;
    logic [63:0] snap_cycles_at_done;
    logic [31:0] snap_data_wr;
    logic [31:0] snap_dm_addr;
    logic [2:0] snap_dm_ctrl;
    logic [31:0] snap_dm_rdata;
    logic [31:0] snap_dm_wdata;
    logic [0:0] snap_dm_wr;
    logic [31:0] snap_ex_alu_result;
    logic [0:0] snap_ex_branch_taken;
    logic [31:0] snap_ex_imm;
    logic [31:0] snap_ex_instruction;
    logic [31:0] snap_ex_pc;
    logic [31:0] snap_ex_rs1_data;
    logic [31:0] snap_ex_rs2_data;
    logic [0:0] snap_flush;
    logic [2:0] snap_funct3;
    logic [6:0] snap_funct7;
    logic [31:0] snap_id_instruction;
    logic [31:0] snap_id_pc;
    logic [31:0] snap_if_instruction;
    logic [31:0] snap_if_pc;
    logic [31:0] snap_imm_out;
    logic [2:0] snap_imm_src;
    logic [63:0] snap_instr_at_done;
    logic [63:0] snap_instr_retired;
    logic [31:0] snap_instruction;
    logic [0:0] snap_load_use_hazard;
    logic [31:0] snap_mem_alu_result;
    logic [31:0] snap_mem_instruction;
    logic [31:0] snap_mem_rs1_data;
    logic [31:0] snap_mem_rs2_data;
    logic [31:0] snap_next_pc;
    logic [6:0] snap_opcode;
    logic [31:0] snap_pc;
    logic [4:0] snap_rd_addr;
    logic [4:0] snap_rs1_addr;
    logic [31:0] snap_rs1_data;
    logic [4:0] snap_rs2_addr;
    logic [31:0] snap_rs2_data;
    logic [1:0] snap_ru_data_wr_src;
    logic [0:0] snap_ru_wr;
    logic [0:0] snap_stall;
    logic [0:0] snap_trap_flush;
    logic [31:0] snap_wb_instruction;
    logic [4:0] snap_wb_rd_addr;
    logic [31:0] snap_wb_rd_data;
    logic [1023:0] snap_reg_values;

    // Derived signals used by the attribute expressions; a signal may come
    // from a snapshot of another group, so it can lag one sweep behind.
    wire stage_if_active  = (snap_if_instruction != 32'h00000000) &&
                             (snap_if_instruction != 32'h00000013);
    wire stage_id_active  = (snap_id_instruction != 32'h00000000) &&
                             (snap_id_instruction != 32'h00000013);
    wire stage_ex_active  = (snap_ex_instruction != 32'h00000000) &&
                             (snap_ex_instruction != 32'h00000013);
    wire stage_mem_active = (snap_mem_instruction != 32'h00000000) &&
                             (snap_mem_instruction != 32'h00000013);
    wire stage_wb_active  = (snap_wb_instruction != 32'h00000000) &&
                             (snap_wb_instruction != 32'h00000013);
    wire mem_access       = (snap_mem_instruction[6:0] == 7'b0000011) ||
                             (snap_mem_instruction[6:0] == 7'b0100011);
    wire mem_write_access = snap_dm_wr;
    wire mem_read_access  = mem_access && !mem_write_access;
    wire mem_access_live  = (mem_instruction[6:0] == 7'b0000011) ||
                             (mem_instruction[6:0] == 7'b0100011);
    wire mem_store_live   = (mem_instruction[6:0] == 7'b0100011);

    // Instruction decode of the instruction in flight.
    wire [31:0] dec_instr  = panel_instruction;
    wire [6:0]  dec_opcode = panel_instruction[6:0];
    wire [2:0]  dec_funct3 = panel_instruction[14:12];
    wire [6:0]  dec_funct7 = panel_instruction[31:25];
    wire [4:0]  dec_rd     = panel_instruction[11:7];
    wire [4:0]  dec_rs1    = panel_instruction[19:15];
    wire [4:0]  dec_rs2    = panel_instruction[24:20];
    wire [11:0] dec_imm_i  = panel_instruction[31:20];
    wire [11:0] dec_imm_s  = {panel_instruction[31:25], panel_instruction[11:7]};
    wire [12:0] dec_imm_b  = {panel_instruction[31], panel_instruction[7],
                               panel_instruction[30:25], panel_instruction[11:8], 1'b0};
    wire [19:0] dec_imm_u  = panel_instruction[31:12];
    wire [20:0] dec_imm_j  = {panel_instruction[31], panel_instruction[19:12],
                               panel_instruction[20], panel_instruction[30:21], 1'b0};

    // 0 = R, 1 = I, 2 = S, 3 = B, 4 = U, 5 = J
    logic [2:0] dec_format;
    always_comb begin
        case (dec_opcode)
            7'b0110011:                            dec_format = 3'd0;  // OP
            7'b0010011, 7'b0000011,
            7'b1100111, 7'b1110011:                dec_format = 3'd1;  // OP-IMM, LOAD, JALR, SYSTEM
            7'b0100011:                            dec_format = 3'd2;  // STORE
            7'b1100011:                            dec_format = 3'd3;  // BRANCH
            7'b0110111, 7'b0010111:                dec_format = 3'd4;  // LUI, AUIPC
            7'b1101111:                            dec_format = 3'd5;  // JAL
            default:                               dec_format = 3'd0;
        endcase
    end

    // The mnemonic of the instruction in flight.
    logic [47:0] dec_mnemonic;
    always_comb begin
        case (dec_opcode)
            7'b0110011: begin
                if (dec_funct7 == 7'b0000001) begin
                    case (dec_funct3)
                        3'b000: dec_mnemonic = "MUL   ";
                        3'b001: dec_mnemonic = "MULH  ";
                        3'b010: dec_mnemonic = "MULHSU";
                        3'b011: dec_mnemonic = "MULHU ";
                        3'b100: dec_mnemonic = "DIV   ";
                        3'b101: dec_mnemonic = "DIVU  ";
                        3'b110: dec_mnemonic = "REM   ";
                        default: dec_mnemonic = "REMU  ";
                    endcase
                end else begin
                    case (dec_funct3)
                        3'b000: dec_mnemonic = dec_funct7[5] ? "SUB   " : "ADD   ";
                        3'b001: dec_mnemonic = "SLL   ";
                        3'b010: dec_mnemonic = "SLT   ";
                        3'b011: dec_mnemonic = "SLTU  ";
                        3'b100: dec_mnemonic = "XOR   ";
                        3'b101: dec_mnemonic = dec_funct7[5] ? "SRA   " : "SRL   ";
                        3'b110: dec_mnemonic = "OR    ";
                        default: dec_mnemonic = "AND   ";
                    endcase
                end
            end
            7'b0010011: begin
                case (dec_funct3)
                    3'b000: dec_mnemonic = "ADDI  ";
                    3'b010: dec_mnemonic = "SLTI  ";
                    3'b011: dec_mnemonic = "SLTIU ";
                    3'b100: dec_mnemonic = "XORI  ";
                    3'b110: dec_mnemonic = "ORI   ";
                    3'b001: dec_mnemonic = "SLLI  ";
                    3'b101: dec_mnemonic = dec_funct7[5] ? "SRAI  " : "SRLI  ";
                    default: dec_mnemonic = "ANDI  ";
                endcase
            end
            7'b0100011: begin
                case (dec_funct3)
                    3'b000: dec_mnemonic = "SB    ";
                    3'b001: dec_mnemonic = "SH    ";
                    default: dec_mnemonic = "SW    ";
                endcase
            end
            7'b0000011: begin
                case (dec_funct3)
                    3'b000: dec_mnemonic = "LB    ";
                    3'b001: dec_mnemonic = "LH    ";
                    3'b100: dec_mnemonic = "LBU   ";
                    3'b101: dec_mnemonic = "LHU   ";
                    default: dec_mnemonic = "LW    ";
                endcase
            end
            7'b1100011: begin
                case (dec_funct3)
                    3'b000: dec_mnemonic = "BEQ   ";
                    3'b001: dec_mnemonic = "BNE   ";
                    3'b100: dec_mnemonic = "BLT   ";
                    3'b101: dec_mnemonic = "BGE   ";
                    3'b110: dec_mnemonic = "BLTU  ";
                    default: dec_mnemonic = "BGEU  ";
                endcase
            end
            7'b1101111: begin
                dec_mnemonic = "JAL   ";
            end
            7'b1100111: begin
                dec_mnemonic = "JALR  ";
            end
            7'b0110111: begin
                dec_mnemonic = "LUI   ";
            end
            7'b0010111: begin
                dec_mnemonic = "AUIPC ";
            end
            default:    dec_mnemonic = "      ";
        endcase
    end

    // The shift-immediate carries the shamt in bits [24:20] and the
    // funct7 of the operation in bits [31:25]: the immediate it really
    // has is the shamt alone.
    wire dec_is_shift_imm = (dec_opcode == 7'b0010011) &&
                            ((dec_funct3 == 3'b001) || (dec_funct3 == 3'b101));
    wire [4:0] dec_shamt = panel_instruction[24:20];

    // The immediate of the decoded format, zero extended.
    wire [31:0] dec_imm = (dec_format == 3'd1) ? (dec_is_shift_imm
                                                 ? {27'd0, dec_shamt}
                                                 : {20'd0, dec_imm_i}) :
                          (dec_format == 3'd2) ? {20'd0, dec_imm_s} :
                          (dec_format == 3'd3) ? {19'd0, dec_imm_b} :
                          (dec_format == 3'd4) ? {12'd0, dec_imm_u} :
                          (dec_format == 3'd5) ? {11'd0, dec_imm_j} : 32'd0;

    // The decimal digit of a register number: the tens first.
    function automatic [7:0] dec_digit(input logic [4:0] value, input int pos);
        logic [5:0] tens;
        begin
            tens = (value >= 10) + (value >= 20) + (value >= 30);
            if (pos == 0)
                dec_digit = 8'd48 + tens;
            else
                dec_digit = 8'd48 + (value - 10 * tens);
        end
    endfunction

    // The character of a cell of the panel: the labels are constant text,
    // the values are decoded from the instruction in flight.
    function automatic [7:0] panel_char(input int unsigned line,
                                        input int unsigned col);
        begin
            case (line)
                0: begin
                    if (col < 5)
                        panel_char = 8'((PANEL_TXT_INSTR >> (8*(4 - col))) & 8'hFF);
                    else if (col < 6)
                        panel_char = 8'h20;
                    else if (col < 14)
                        panel_char = hex_digit(dec_instr, 13 - col);
                    else
                        panel_char = 8'h20;  // ' '
                end
                1: begin
                    if (col < 4)
                        panel_char = 8'((PANEL_TXT_MNEM >> (8*(3 - col))) & 8'hFF);
                    else if (col < 6)
                        panel_char = 8'h20;
                    else if (col < 12)
                        panel_char = 8'((dec_mnemonic >> (8*(11 - col))) & 8'hFF);
                    else
                        panel_char = 8'h20;  // ' '
                end
                2: begin
                    if (col < 3)
                        panel_char = 8'((PANEL_TXT_RD >> (8*(2 - col))) & 8'hFF);
                    else if (col < 5)
                        panel_char = ((dec_format == 3'd2 || dec_format == 3'd3) ? 8'h2D : dec_digit(dec_rd, col - 3));
                    else if (col < 6)
                        panel_char = 8'h20;
                    else if (col < 10)
                        panel_char = 8'((PANEL_TXT_RS1 >> (8*(9 - col))) & 8'hFF);
                    else if (col < 12)
                        panel_char = ((dec_format == 3'd4 || dec_format == 3'd5) ? 8'h2D : dec_digit(dec_rs1, col - 10));
                    else if (col < 13)
                        panel_char = 8'h20;
                    else if (col < 17)
                        panel_char = 8'((PANEL_TXT_RS2 >> (8*(16 - col))) & 8'hFF);
                    else if (col < 19)
                        panel_char = ((dec_format == 3'd0 || dec_format == 3'd2) ? dec_digit(dec_rs2, col - 17) : 8'h2D);
                    else
                        panel_char = 8'h20;  // ' '
                end
                3: begin
                    if (col < 4)
                        panel_char = 8'((PANEL_TXT_IMM >> (8*(3 - col))) & 8'hFF);
                    else if (col < 12)
                        panel_char = hex_digit(dec_imm, 11 - col);
                    else
                        panel_char = 8'h20;  // ' '
                end
                default: panel_char = 8'h20;  // ' '
            endcase
        end
    endfunction

    // The attribute of a cell of the panel: the labels wear the body
    // colour, every value the colour of its kind.
    function automatic [7:0] panel_attr(input int unsigned line,
                                        input int unsigned col);
        begin
            case (line)
                0: panel_attr = (col >= 6 && col < 14) ? 8'h08 : 8'h09;
                1: panel_attr = (col >= 6 && col < 12) ? 8'h0F : 8'h09;
                2: panel_attr = (col >= 3 && col < 5) || (col >= 10 && col < 12) || (col >= 17 && col < 19) ? 8'h0D : 8'h09;
                3: panel_attr = (col >= 4 && col < 12) ? 8'h0C : 8'h09;
                default: panel_attr = 8'h09;
            endcase
        end
    endfunction

    // The table follows the running value.  The window and the marked row are
    // sampled at the sweep boundary, so every row of a sweep shows the
    // same window.
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            tbl_prog_memory_word <= '0;
            tbl_prog_memory_access_base <= '0;
            tbl_prog_memory_access_word <= '0;
            tbl_prog_memory_access_write <= 1'b0;
            tbl_prog_memory_access_valid <= 1'b0;
        end else begin
            tbl_prog_memory_word <= imem_rd_data;
            if (1'b1) begin
                tbl_prog_memory_access_base <= tbl_prog_memory_clamped;
                tbl_prog_memory_access_word <= tbl_prog_memory_hit_word;
                tbl_prog_memory_access_write <= 1'b0;
                tbl_prog_memory_access_valid <= 1'b1;
            end
        end
    end
    // The table follows the last access.  The window and the marked row are
    // sampled at the sweep boundary, so every row of a sweep shows the
    // same window.
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            tbl_data_memory_word <= '0;
            tbl_data_memory_access_base <= '0;
            tbl_data_memory_access_word <= '0;
            tbl_data_memory_access_write <= 1'b0;
            tbl_data_memory_access_valid <= 1'b0;
        end else begin
            tbl_data_memory_word <= dmem_rd_data;
            if (mem_access_live) begin
                tbl_data_memory_access_base <= tbl_data_memory_clamped;
                tbl_data_memory_access_word <= tbl_data_memory_hit_word;
                tbl_data_memory_access_write <= mem_store_live;
                tbl_data_memory_access_valid <= 1'b1;
            end
        end
    end
    // Helper functions: value --> ASCII
    function automatic [7:0] hex_digit (
        input logic [63:0] value,
        input int          nibble
    );
        logic [63:0] shifted;
        logic [3:0]  d;
        shifted = value >> (nibble * 4);
        d = shifted[3:0];
        hex_digit = (d < 4'd10) ? (8'd48 + d) : (8'd55 + d);  // '0'-'9', 'A'-'F'
    endfunction

    function automatic [7:0] bin_digit (
        input logic [63:0] value,
        input int          bit_idx
    );
        logic [63:0] shifted;
        shifted = value >> bit_idx;
        bin_digit = 8'd48 + shifted[0];  // '0' or '1'
    endfunction

    // Round-robin FSM - one char per cycle, groups alternate
    logic        wr_en;
    logic [12:0] wr_addr;
    logic [7:0]  wr_data;
    logic [7:0]  wr_attr;

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            grp_ctr <= '0;
            reg_value <= '0;
            reg_addr  <= '0;
            reg_col   <= '0;
            snap_alu_a <= '0;
            snap_alu_b <= '0;
            snap_alu_op <= '0;
            snap_alu_res <= '0;
            snap_alua_src <= '0;
            snap_alub_src <= '0;
            snap_br_op <= '0;
            snap_branch <= '0;
            snap_branch_flush <= '0;
            snap_cycles_at_done <= '0;
            snap_data_wr <= '0;
            snap_dm_addr <= '0;
            snap_dm_ctrl <= '0;
            snap_dm_rdata <= '0;
            snap_dm_wdata <= '0;
            snap_dm_wr <= '0;
            snap_ex_alu_result <= '0;
            snap_ex_branch_taken <= '0;
            snap_ex_imm <= '0;
            snap_ex_instruction <= '0;
            snap_ex_pc <= '0;
            snap_ex_rs1_data <= '0;
            snap_ex_rs2_data <= '0;
            snap_flush <= '0;
            snap_funct3 <= '0;
            snap_funct7 <= '0;
            snap_id_instruction <= '0;
            snap_id_pc <= '0;
            snap_if_instruction <= '0;
            snap_if_pc <= '0;
            snap_imm_out <= '0;
            snap_imm_src <= '0;
            snap_instr_at_done <= '0;
            snap_instr_retired <= '0;
            snap_instruction <= '0;
            snap_load_use_hazard <= '0;
            snap_mem_alu_result <= '0;
            snap_mem_instruction <= '0;
            snap_mem_rs1_data <= '0;
            snap_mem_rs2_data <= '0;
            snap_next_pc <= '0;
            snap_opcode <= '0;
            snap_pc <= '0;
            snap_rd_addr <= '0;
            snap_rs1_addr <= '0;
            snap_rs1_data <= '0;
            snap_rs2_addr <= '0;
            snap_rs2_data <= '0;
            snap_ru_data_wr_src <= '0;
            snap_ru_wr <= '0;
            snap_stall <= '0;
            snap_trap_flush <= '0;
            snap_wb_instruction <= '0;
            snap_wb_rd_addr <= '0;
            snap_wb_rd_data <= '0;
            snap_reg_values <= '0;
            ctr_proc <= '0;
            ctr_proc1 <= '0;
            ctr_proc2 <= '0;
            ctr_proc3 <= '0;
            ctr_regs <= '0;
            ctr_tbl_prog_memory <= '0;
            ctr_tbl_data_memory <= '0;
            tbl_prog_memory_row <= '0;
            tbl_prog_memory_col <= '0;
            tbl_prog_memory_base <= '0;
            tbl_prog_memory_addr <= '0;
            tbl_prog_memory_marked <= '0;
            tbl_prog_memory_marked_write <= 1'b0;
            tbl_prog_memory_marked_valid <= 1'b0;
            imem_rd_addr <= '0;
            tbl_data_memory_row <= '0;
            tbl_data_memory_col <= '0;
            tbl_data_memory_base <= '0;
            tbl_data_memory_addr <= '0;
            tbl_data_memory_marked <= '0;
            tbl_data_memory_marked_write <= 1'b0;
            tbl_data_memory_marked_valid <= 1'b0;
            dmem_rd_addr <= '0;
            panel_line <= '0;
            panel_col <= '0;
            panel_instruction <= '0;
        end else begin
            grp_ctr <= (grp_ctr == N_GROUPS - 1) ? '0 : grp_ctr + 1'b1;
            case (grp_ctr)
                GRP_PROC: begin
                    ctr_proc <= (ctr_proc == N_PROC - 1) ? '0 : ctr_proc + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_proc == N_PROC - 1) begin
                    snap_cycles_at_done <= cycles_at_done;
                    snap_instr_at_done <= instr_at_done;
                    snap_ru_data_wr_src <= ru_data_wr_src;
                    snap_pc <= pc;
                    snap_rs1_addr <= rs1_addr;
                    snap_rs2_addr <= rs2_addr;
                    snap_rd_addr <= rd_addr;
                    snap_instruction <= instruction;
                    snap_next_pc <= next_pc;
                    snap_data_wr <= data_wr;
                    snap_ru_wr <= ru_wr;
                    snap_if_pc <= if_pc;
                    snap_if_instruction <= if_instruction;
                    snap_branch <= branch;
                    snap_rs1_data <= rs1_data;
                    snap_rs2_data <= rs2_data;
                    snap_mem_alu_result <= mem_alu_result;
                    snap_wb_instruction <= wb_instruction;
                    end
                end
                GRP_PROC1: begin
                    ctr_proc1 <= (ctr_proc1 == N_PROC1 - 1) ? '0 : ctr_proc1 + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_proc1 == N_PROC1 - 1) begin
                    snap_imm_out <= imm_out;
                    snap_imm_src <= imm_src;
                    snap_wb_rd_addr <= wb_rd_addr;
                    snap_wb_rd_data <= wb_rd_data;
                    snap_opcode <= opcode;
                    snap_funct3 <= funct3;
                    snap_funct7 <= funct7;
                    snap_id_pc <= id_pc;
                    snap_id_instruction <= id_instruction;
                    snap_dm_addr <= dm_addr;
                    snap_ex_pc <= ex_pc;
                    snap_dm_wdata <= dm_wdata;
                    snap_ex_instruction <= ex_instruction;
                    snap_dm_rdata <= dm_rdata;
                    snap_ex_rs1_data <= ex_rs1_data;
                    snap_dm_ctrl <= dm_ctrl;
                    snap_stall <= stall;
                    snap_ex_rs2_data <= ex_rs2_data;
                    snap_dm_wr <= dm_wr;
                    snap_load_use_hazard <= load_use_hazard;
                    snap_ex_imm <= ex_imm;
                    snap_branch_flush <= branch_flush;
                    snap_trap_flush <= trap_flush;
                    snap_flush <= flush;
                    snap_alu_a <= alu_a;
                    end
                end
                GRP_PROC2: begin
                    ctr_proc2 <= (ctr_proc2 == N_PROC2 - 1) ? '0 : ctr_proc2 + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_proc2 == N_PROC2 - 1) begin
                    snap_mem_rs1_data <= mem_rs1_data;
                    snap_alu_b <= alu_b;
                    snap_mem_rs2_data <= mem_rs2_data;
                    snap_alu_res <= alu_res;
                    snap_ex_alu_result <= ex_alu_result;
                    snap_alu_op <= alu_op;
                    snap_br_op <= br_op;
                    snap_mem_instruction <= mem_instruction;
                    snap_alua_src <= alua_src;
                    snap_alub_src <= alub_src;
                    snap_ex_branch_taken <= ex_branch_taken;
                    snap_instr_retired <= instr_retired;
                    end
                end
                GRP_PROC3: begin
                    ctr_proc3 <= (ctr_proc3 == N_PROC3 - 1) ? '0 : ctr_proc3 + 1'b1;
                end
                GRP_REGS: begin
                    ctr_regs <= (ctr_regs == N_REGS - 1) ? '0 : ctr_regs + 1'b1;
                    // Load the bank at the end of a sweep, so the next sweep
                    // renders every character from the same captured instant.
                    if (ctr_regs == N_REGS - 1) begin
                    snap_reg_values <= reg_values;
                    end
                    // Stage 1: select the register row of this character.
                    reg_value <= snap_reg_values[32*ctr_regs[7:3] +: 32];
                    reg_addr  <= REG_ADDR[13*ctr_regs[7:3] +: 13];
                    reg_col   <= ctr_regs[2:0];
                end
                GRP_TBL_PROG_MEMORY: begin
                    ctr_tbl_prog_memory <= (ctr_tbl_prog_memory == N_TBL_PROG_MEMORY - 1) ? '0 : ctr_tbl_prog_memory + 1'b1;
                    if (ctr_tbl_prog_memory == N_TBL_PROG_MEMORY - 1) begin
                        // A new sweep: the window keeps the running value in view.
                        tbl_prog_memory_row <= 6'd0;
                        tbl_prog_memory_col <= 4'd0;
                        tbl_prog_memory_base <= tbl_prog_memory_next_base;
                        tbl_prog_memory_addr <= tbl_prog_memory_next_base;
                        tbl_prog_memory_marked <= tbl_prog_memory_access_word;
                        tbl_prog_memory_marked_write <= tbl_prog_memory_access_write;
                        tbl_prog_memory_marked_valid <= tbl_prog_memory_access_valid;
                        imem_rd_addr <= tbl_prog_memory_next_base * 4;
                    end else if (tbl_prog_memory_col == 4'd13) begin
                        tbl_prog_memory_col <= 4'd0;
                        tbl_prog_memory_row <= tbl_prog_memory_row + 6'd1;
                        tbl_prog_memory_addr <= tbl_prog_memory_base + {8'd0, tbl_prog_memory_row} + 14'd1;
                        imem_rd_addr <= (tbl_prog_memory_base + {8'd0, tbl_prog_memory_row} + 14'd1) * 4;
                    end else begin
                        tbl_prog_memory_col <= tbl_prog_memory_col + 4'd1;
                    end
                end
                GRP_TBL_DATA_MEMORY: begin
                    ctr_tbl_data_memory <= (ctr_tbl_data_memory == N_TBL_DATA_MEMORY - 1) ? '0 : ctr_tbl_data_memory + 1'b1;
                    if (ctr_tbl_data_memory == N_TBL_DATA_MEMORY - 1) begin
                        // A new sweep: the window keeps the last access in view.
                        tbl_data_memory_row <= 6'd0;
                        tbl_data_memory_col <= 4'd0;
                        tbl_data_memory_base <= tbl_data_memory_next_base;
                        tbl_data_memory_addr <= tbl_data_memory_next_base;
                        tbl_data_memory_marked <= tbl_data_memory_access_word;
                        tbl_data_memory_marked_write <= tbl_data_memory_access_write;
                        tbl_data_memory_marked_valid <= tbl_data_memory_access_valid;
                        dmem_rd_addr <= tbl_data_memory_next_base * 4;
                    end else if (tbl_data_memory_col == 4'd13) begin
                        tbl_data_memory_col <= 4'd0;
                        tbl_data_memory_row <= tbl_data_memory_row + 6'd1;
                        tbl_data_memory_addr <= tbl_data_memory_base + {8'd0, tbl_data_memory_row} + 14'd1;
                        dmem_rd_addr <= (tbl_data_memory_base + {8'd0, tbl_data_memory_row} + 14'd1) * 4;
                    end else begin
                        tbl_data_memory_col <= tbl_data_memory_col + 4'd1;
                    end
                end
                GRP_PANEL: begin
                    if (panel_col == PANEL_CHARS - 1) begin
                        panel_col <= 5'd0;
                        panel_line <= panel_line + 2'd1;
                        // The next sweep decodes the instruction the bank
                        // holds now: the word and its decode have to
                        // describe the same instruction.
                        if (panel_line == PANEL_LINES - 1)
                            panel_instruction <= snap_ex_instruction;
                    end else begin
                        panel_col <= panel_col + 5'd1;
                    end
                end
                default: ;  // no write
            endcase
        end
    end

